CREATE OR REPLACE FUNCTION public.record_user_streak_activity(p_user_id uuid)
 RETURNS TABLE(user_id uuid, current_streak integer, effective_streak integer, longest_streak integer, last_active_date date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_today date := (now() at time zone 'America/Sao_Paulo')::date;
  v_current_streak integer;
  v_longest_streak integer;
  v_last_active_date date;
begin
  if p_user_id is null then
    raise exception 'p_user_id is required';
  end if;

  perform 1
  from public.profiles as profile
  where profile.user_id = p_user_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Profile not found';
  end if;

  insert into public.user_streaks (user_id)
  values (p_user_id)
  on conflict on constraint user_streaks_pkey do nothing;

  select
    streak.current_streak,
    streak.longest_streak,
    streak.last_active_date
  into
    v_current_streak,
    v_longest_streak,
    v_last_active_date
  from public.user_streaks as streak
  where streak.user_id = p_user_id
  for update;

  if v_last_active_date is null then
    v_current_streak := 1;
  elsif v_last_active_date = v_today then
    null;
  elsif v_last_active_date = v_today - 1 then
    v_current_streak := v_current_streak + 1;
  elsif v_last_active_date < v_today - 1 then
    v_current_streak := 1;
  else
    raise exception 'last_active_date cannot be in the future';
  end if;

  v_longest_streak := greatest(v_longest_streak, v_current_streak);

  update public.user_streaks as streak
  set
    current_streak = v_current_streak,
    longest_streak = v_longest_streak,
    last_active_date = v_today
  where streak.user_id = p_user_id;

  update public.profiles as profile
  set
    streak = v_current_streak,
    last_activity_date = v_today
  where profile.user_id = p_user_id;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Profile not found during compatibility synchronization';
  end if;

  return query
  select
    streak.user_id,
    streak.current_streak,
    streak.current_streak as effective_streak,
    streak.longest_streak,
    streak.last_active_date
  from public.user_streaks as streak
  where streak.user_id = p_user_id;
end;
$function$

complete_mission_with_energy.function_definition:
CREATE OR REPLACE FUNCTION public.complete_mission_with_energy(p_mission_id uuid)
 RETURNS TABLE(mission_id uuid, completed_now boolean, energy_awarded integer, total_energy integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_mission_completed boolean;
  v_energy_reward integer;
  v_total_energy integer;
begin
  if v_user_id is null then
    raise exception using
      errcode = '28000',
      message = 'Authentication required';
  end if;

  if p_mission_id is null then
    raise exception using
      errcode = '22004',
      message = 'Mission id is required';
  end if;

  select
    mission.completed,
    greatest(coalesce(mission.xp_reward, 0), 0)
  into v_mission_completed, v_energy_reward
  from public.daily_missions as mission
  where mission.id = p_mission_id
    and mission.user_id = v_user_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Mission not found';
  end if;

  if v_mission_completed then
    select greatest(coalesce(profile.total_xp, 0), 0)
    into v_total_energy
    from public.profiles as profile
    where profile.user_id = v_user_id;

    if not found then
      raise exception using
        errcode = 'P0002',
        message = 'Profile not found';
    end if;

    return query select p_mission_id, false, 0, v_total_energy;
    return;
  end if;

  if v_energy_reward <= 0 or v_energy_reward > 500 then
    raise exception using
      errcode = '22023',
      message = 'Mission Energy reward is invalid';
  end if;

  update public.profiles as profile
  set
    total_xp = greatest(coalesce(profile.total_xp, 0) + v_energy_reward, 0),
    level = greatest(
      1,
      floor(
        greatest(coalesce(profile.total_xp, 0) + v_energy_reward, 0)::numeric
        / 500
      )::integer + 1
    )
  where profile.user_id = v_user_id
  returning profile.total_xp into v_total_energy;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Profile not found';
  end if;

  update public.daily_missions as mission
  set
    completed = true,
    current_value = greatest(
      coalesce(mission.current_value, 0),
      coalesce(mission.target_value, 1)
    ),
    completed_at = coalesce(mission.completed_at, now())
  where mission.id = p_mission_id
    and mission.user_id = v_user_id
    and mission.completed = false;

  if not found then
    raise exception using
      errcode = '40001',
      message = 'Mission state changed during completion';
  end if;

  insert into public.reward_transactions (
    user_id,
    reward_type,
    source_type,
    source_id,
    idempotency_key,
    payload
  )
  values (
    v_user_id,
    'energy',
    'daily_mission_completion',
    p_mission_id::text,
    'daily_mission_completion:' || p_mission_id::text,
    jsonb_build_object(
      'mission_id', p_mission_id,
      'amount', v_energy_reward
    )
  );

  perform public.record_user_streak_activity(v_user_id);

  return query select
    p_mission_id,
    true,
    v_energy_reward,
    v_total_energy;
end;
$function$
